<?php
declare(strict_types=1);
session_start(); require_once dirname(__DIR__) . '/api/config.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
$db=db(); $editing=null; $creating=isset($_GET['create']);
if(isset($_GET['edit'])){$q=$db->prepare('SELECT * FROM products WHERE id=? LIMIT 1');$q->execute([(string)$_GET['edit']]);$editing=$q->fetch()?:null;}
$products=$db->query('SELECT id,storefront,name,short_description,price,old_price,category,image,tag,is_active FROM products ORDER BY sort_order ASC,created_at DESC')->fetchAll();
function productEscape(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');} function productImage(string $v):string{return preg_match('#^(https?:)?//#',$v)?$v:'../'.ltrim($v,'/');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products - Electra admin</title><link rel="stylesheet" href="admin.css"><style>.product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px}.product-card{overflow:hidden;border:1px solid var(--line);border-radius:14px;background:#fff;cursor:grab}.product-card.dragging{opacity:.45;border:2px dashed var(--gold)}.product-card.drop-target{box-shadow:0 0 0 3px var(--gold-light)}.product-image{width:100%;height:220px;display:block;object-fit:cover;background:#f2f2f2}.product-card-body{padding:18px}.product-card h3{margin:0 0 6px;font-size:17px}.product-card p{min-height:38px;margin:0 0 12px;color:var(--muted);font-size:13px}.product-meta{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.product-actions{display:flex;gap:8px}.product-actions a,.product-actions button{padding:9px 12px;border-radius:7px;font:700 12px inherit;text-decoration:none;cursor:pointer}.product-actions a{border:1px solid var(--line);background:#fff;color:var(--ink)}.product-actions button{border:1px solid #e3b9b3;background:#fff7f6;color:#a33b30}.product-editor{max-width:760px;margin-bottom:24px}.product-editor form{display:grid;gap:14px}.product-editor label{display:grid;gap:6px;color:var(--muted);font-size:13px;font-weight:700}.product-editor input,.product-editor textarea,.product-editor select{width:100%;padding:11px;border:1px solid var(--line);border-radius:7px;font:inherit}.product-editor textarea{min-height:80px;resize:vertical}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-grid .full{grid-column:1/-1}.editor-actions{display:flex;gap:10px}.editor-actions button,.editor-actions a{padding:11px 16px;border:0;border-radius:8px;background:#11100e;color:#e6cd93;text-decoration:none;font:700 13px inherit;cursor:pointer}.editor-actions a{background:#fff;color:var(--ink);border:1px solid var(--line)}.heading-actions{display:flex;align-items:center;gap:10px}.upload-label{padding:12px;border:1px dashed var(--gold);border-radius:8px;background:var(--gold-pale)}.reorder-note{margin:0 0 18px;color:var(--muted);font-size:13px}@media(max-width:600px){.product-grid{grid-template-columns:1fr}.product-image{height:240px}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">E</span><span>Electra</span></a><p class="nav-label">Store management</p><nav class="side-nav"><a href="index.php"><span>Overview</span></a><a class="active" href="products.php"><span>Products</span></a><a href="orders.php"><span>Orders</span></a><a href="payments.php"><span>Payments</span></a></nav><p class="nav-label bottom-label">General</p><nav class="side-nav"><a href="index.php?view=settings"><span>Settings</span></a><a class="sign-out" href="logout.php"><span>Sign out</span></a></nav><div class="sidebar-foot"><i></i> Store online</div></aside><main class="workspace"><header class="workspace-header"><div><p class="kicker">Electra store</p><h1>Products</h1></div><div class="profile"><span class="avatar"><?=productEscape(strtoupper(substr((string)$_SESSION['admin_name'],0,1)))?></span><span><strong><?=productEscape((string)$_SESSION['admin_name'])?></strong><small>Store manager</small></span></div></header><?php if($editing||$creating): ?><section class="card product-editor"><div class="card-heading"><div><p class="section-kicker">Catalog</p><h2><?=$editing?'Edit product':'Create new product'?></h2></div><?php if($editing): ?><img src="<?=productEscape(productImage((string)$editing['image']))?>" alt="" style="width:72px;height:72px;object-fit:cover;border-radius:8px"><?php endif; ?></div><form method="post" action="product-actions.php" enctype="multipart/form-data"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><?php if($editing): ?><input type="hidden" name="id" value="<?=productEscape((string)$editing['id'])?>"><?php else: ?><label>Product ID<input name="id" placeholder="e.g. signature-perfume" required></label><?php endif; ?><div class="form-grid"><label>Product name<input name="name" value="<?=productEscape((string)($editing['name']??''))?>" required></label><label>Storefront<select name="storefront"><option value="elys-beauty" <?=($editing['storefront']??'elys-beauty')==='elys-beauty'?'selected':''?>>Elys Beauty</option><option value="fitness" <?=($editing['storefront']??'')==='fitness'?'selected':''?>>Fitness</option></select></label><label>Category<input name="category" value="<?=productEscape((string)($editing['category']??''))?>" placeholder="Perfume"></label><label>Tag<input name="tag" value="<?=productEscape((string)($editing['tag']??''))?>" placeholder="Bestseller"></label><label>Price<input type="number" name="price" min="0" step="0.01" value="<?=productEscape((string)($editing['price']??''))?>" required></label><label>Old price<input type="number" name="old_price" min="0" step="0.01" value="<?=productEscape((string)($editing['old_price']??''))?>"></label><label class="full">Short description<textarea name="short_description"><?=productEscape((string)($editing['short_description']??''))?></textarea></label><label class="full">Full description<textarea name="description"><?=productEscape((string)($editing['description']??''))?></textarea></label></div><label class="upload-label">Choose image from your desktop/media<input type="file" name="image_upload" accept="image/jpeg,image/png,image/gif,image/webp" <?=$editing?'':'required'?>></label><label><input type="checkbox" name="is_active" value="1" <?=!$editing||(int)$editing['is_active']===1?'checked':''?>> Visible in storefront</label><div class="editor-actions"><button type="submit"><?=$editing?'Save changes':'Create product'?></button><a href="products.php">Cancel</a></div></form></section><?php endif; ?><section class="page-heading"><div><p class="section-kicker">Catalog</p><h2>Storefront products</h2><p>Drag products to set their storefront order.</p></div><div class="heading-actions"><span class="select-pill"><?=count($products)?> products</span><a class="primary-button" href="?create=1">Create new product</a></div></section><p class="reorder-note" id="reorderStatus"></p><section class="product-grid" id="productGrid"><?php foreach($products as $product): ?><article class="product-card" draggable="true" data-product-id="<?=productEscape((string)$product['id'])?>"><img class="product-image" src="<?=productEscape(productImage((string)$product['image']))?>" alt="<?=productEscape((string)$product['name'])?>"><div class="product-card-body"><h3><?=productEscape((string)$product['name'])?></h3><p><?=productEscape((string)($product['short_description']?:$product['id']))?></p><div class="product-meta"><strong>₦<?=number_format((float)$product['price'],2)?></strong><span class="status <?=((int)$product['is_active']===1?'approved':'awaiting')?>"><?=((int)$product['is_active']===1?'Visible':'Hidden')?></span></div><div class="product-actions"><a href="?edit=<?=rawurlencode((string)$product['id'])?>">Edit</a><form method="post" action="product-actions.php" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=productEscape((string)$product['id'])?>"><button type="submit">Delete</button></form></div></div></article><?php endforeach; ?></section></main></div><script>const grid=document.getElementById('productGrid'),status=document.getElementById('reorderStatus');let dragged=null;grid.querySelectorAll('.product-card').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',()=>{card.classList.remove('dragging');dragged=null});card.addEventListener('dragover',e=>{e.preventDefault()});card.addEventListener('drop',async e=>{e.preventDefault();if(!dragged||dragged===card)return;const all=[...grid.children],from=all.indexOf(dragged),to=all.indexOf(card);grid.insertBefore(dragged,from<to?card.nextSibling:card);const body=new URLSearchParams({action:'reorder'});[...grid.children].forEach(item=>body.append('order_ids[]',item.dataset.productId));status.textContent='Saving order...';const response=await fetch('product-actions.php',{method:'POST',body});status.textContent=response.ok?'Order saved':'Could not save order'})});</script></body></html>
